<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title><?= esc($title ?? 'Program–Subject Mapping') ?> | MCQBank</title>
<style>
:root{--navy:#17365d;--blue:#2463a6;--line:#dbe4ef;--muted:#65758b;--bg:#f4f7fb;--green:#176b45;--red:#a52c2c}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.5 Arial,Helvetica,sans-serif;color:#1e293b}.wrap{max-width:1160px;margin:0 auto;padding:24px 20px}.site-header{background:linear-gradient(105deg,#102d50,#214f80);color:#fff;padding:22px 24px;display:flex;justify-content:space-between;align-items:center;gap:20px}.site-brand{font-size:12px;font-weight:700;letter-spacing:.4px;margin:0 0 7px;color:#e4edf8}.site-title{font-size:29px;line-height:1.2;font-weight:700;margin:0;color:#fff}.header-link{display:inline-block;background:#fff;color:#17365d;text-decoration:none;border-radius:9px;padding:11px 16px;font-weight:700;white-space:nowrap}.head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.head h1{font-size:25px;margin:0;color:var(--navy)}.sub{color:var(--muted);margin:5px 0 0}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px;box-shadow:0 5px 20px #17365d0b}.row{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.field{flex:1;min-width:230px}label{display:block;font-weight:700;margin-bottom:7px;color:#34465e}select{width:100%;padding:11px;border:1px solid #cbd6e4;border-radius:8px;background:#fff;font-size:15px}.btn{display:inline-block;border:0;border-radius:8px;padding:10px 15px;background:var(--blue);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.secondary{background:#eaf0f7;color:var(--navy)}.notice{padding:11px 13px;border-radius:8px;margin-bottom:14px}.success{background:#eaf8f0;color:var(--green)}.error{background:#fff0f0;color:var(--red)}.dept{border:1px solid var(--line);border-radius:10px;margin:14px 0;overflow:hidden}.dept h3{font-size:16px;background:#eef4fb;color:var(--navy);padding:12px 15px;margin:0}.subjects{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px;padding:14px}.subject{display:flex;align-items:flex-start;gap:9px;border:1px solid #e1e8f0;border-radius:8px;padding:10px;cursor:pointer}.subject input{margin-top:4px;accent-color:var(--blue)}.empty{color:var(--muted);padding:18px;background:#f8fafc;border-radius:8px}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.hint{color:var(--muted);font-size:13px;margin-top:8px}@media(max-width:600px){.head{align-items:flex-start;flex-direction:column}.panel{padding:14px}.site-header{align-items:flex-start;flex-direction:column}.site-title{font-size:24px}.wrap{padding:16px 12px}}
</style></head>
<body><header class="site-header"><div><p class="site-brand">Riphah International University (Peshawar Campus)</p><h1 class="site-title">Program–Subject Mapping</h1></div><a class="header-link" href="<?= site_url('dashboard/admin') ?>">← Admin Dashboard</a></header><main class="wrap">
<p class="sub" style="margin:0 0 18px">Assign existing subjects to a program without duplicating subject records.</p>
<?php if (session()->getFlashdata('success')): ?><div class="notice success"><?= esc(session()->getFlashdata('success')) ?></div><?php endif; ?>
<?php if (session()->getFlashdata('error')): ?><div class="notice error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?>
<div class="panel"><form method="get" action="<?= site_url('master/program-subjects') ?>"><div class="row"><div class="field"><label for="progId">Select Program</label><select id="progId" name="progId" required onchange="this.form.submit()"><option value="">-- Select Program --</option><?php foreach ($programs as $p): ?><option value="<?= (int)$p['progId'] ?>" <?= (int)$selectedProgram === (int)$p['progId'] ? 'selected' : '' ?>><?= esc($p['progName']) ?></option><?php endforeach; ?></select></div></div><p class="hint">Only departments already linked to the selected program are shown.</p></form></div>
<?php if ($selectedProgram > 0): ?><form method="post" action="<?= site_url('master/program-subjects/save') ?>">
<?= csrf_field() ?><input type="hidden" name="progId" value="<?= (int)$selectedProgram ?>">
<div class="panel"><h2 style="margin:0 0 5px;color:var(--navy);font-size:19px">Available Subjects</h2><p class="sub">Tick the subjects taught in this program, then save. Existing subject records remain shared across programs.</p>
<?php if (!$allowedDepartments): ?><div class="empty">No active Department–Program mappings were found for this program. Please map the department first in Program–Department Mapping.</div><?php else: ?>
<?php foreach ($allowedDepartments as $dept): $deptId=(int)$dept['department_id']; $items=$subjectsByDepartment[$deptId] ?? []; ?>
<section class="dept"><h3><?= esc($dept['department_name']) ?></h3><div class="subjects">
<?php if (!$items): ?><div class="empty">No subjects are currently registered under this department.</div><?php else: foreach ($items as $subject): $sid=(int)$subject['subject_id']; ?><label class="subject"><input type="checkbox" name="subject_ids[]" value="<?= $sid ?>" <?= in_array($sid, $selectedSubjects, true) ? 'checked' : '' ?>><span><?= esc($subject['subject_name']) ?></span></label><?php endforeach; endif; ?>
</div></section><?php endforeach; ?>
<div class="actions"><button type="submit" class="btn">Save Subject Mapping</button><a class="btn secondary" href="<?= site_url('master/program-subjects?progId='.(int)$selectedProgram) ?>">Cancel</a></div>
<?php endif; ?></div></form><?php endif; ?>
</main></body></html>
